/*
 * THE BACKDROP FROSTED NEEDS: a frosted material over a blank stage has nothing to blur, so every frosted
 * example sits on one of these. Ours, not a photograph: dark satin folds with film grain, generated by
 * `tools/frost-backdrop` and served from `public/demos/frost/`. Dark in both schemes on purpose: frosted is
 * a material laid over something, and a neutral deep ground makes its own tint and blur the thing read.
 *
 *  - `frostBackdrop`        16:9 still, the default for any wide stage.
 *  - `frostBackdropTall`    4:3 still, for stages nearer square (a comparison cell, a small card).
 *  - `frostBackdropMotion`  the same satin as a vector that slowly moves (it holds still under
 *                           prefers-reduced-motion), for the ONE stage on screen at a time: the hook playground.
 *
 * One definition, used everywhere a frosted example needs ground: `--docs-frost-backdrop` and
 * `--docs-frost-backdrop-motion` for the page's cards and the hook playground (written by `Base.astro`), and
 * straight into the demo trees that stage themselves, which render in frames that do not carry the page's
 * custom properties. A colour follows the image so a stage is never see-through while it loads.
 */
const ground = "#0a0a0c";
const still = (file: string) => `${ground} center / cover url('/demos/frost/${file}')`;

export const frostBackdrop = still("frost-satin-16x9.jpg");
export const frostBackdropTall = still("frost-satin-4x3.jpg");
export const frostBackdropMotion = still("frost-satin-16x9.svg");
